<?php if($tab==='mine'):?><form method="post" class="rm-card rm-form"><?php rm_fields('preferences',['version'=>$preferences['version']]);?><h2>My Delivery Preferences</h2><label class="rm-check"><input type="checkbox" checked disabled><span><strong>In-App Reminders</strong><small>Always available for your authorized work.</small></span></label><label class="rm-check"><input type="checkbox" name="email" value="1" <?=$preferences['email']?'checked':''?>><span><strong>Email</strong><small><?=access_h($preferences['email_address'])?> · <?=$preferences['email_verified']?'Ownership Verified':'Verification Required'?></small></span></label><label class="rm-check"><input type="checkbox" name="whatsapp" value="1" <?=$preferences['whatsapp']?'checked':''?>><span><strong>WhatsApp</strong><small><?=$preferences['whatsapp_verified']?'Ownership Verified':'Verification Required'?></small></span></label><label>Your WhatsApp Notification Number<input type="tel" name="phone" value="<?=access_h($preferences['phone'])?>" maxlength="16" placeholder="+233…" autocomplete="tel"><small>Include + and your country code. Changing this number requires fresh ownership verification.</small></label><label class="rm-check"><input type="checkbox" name="consent" value="1" <?=$preferences['consent']?'checked':''?>><span>I Agree To Receive Operational Reminders On WhatsApp. I Can Turn Them Off Here.</span></label><p class="rm-warning">Optional delivery requires a ready service and independently verified contact ownership. The owner verifies your enabled contact. In-app remains available while setup is pending.</p><div class="rm-actions"><button class="rm-primary">Save Preferences</button><?php rm_button('Cancel');?></div></form>
<?php elseif($tab==='rules'):?><form method="post" class="rm-card rm-form"><?php rm_fields('rules',['version'=>$rules['version']]);?><h2>Simple Reminder Rules</h2><label>Daily Reminder Time (UTC)<input type="time" name="daily_time" value="<?=access_h($rules['daily_time'])?>" required></label><label>Weekly Auditor<select name="weekly_auditor"><option value="0">Not Assigned · Notify Owner</option><?php foreach($auditors as $person):?><option value="<?=(int)$person['id']?>" <?=(int)$rules['weekly_auditor']===(int)$person['id']?'selected':''?>><?=access_h($person['name'])?></option><?php endforeach?></select></label><p>Sunday reminders use the existing audit registers and the authorized auditor selected here. Missing coverage stays visible; no audit finding is invented.</p><p>New action needs appear in-app at the next check. Outstanding work is reminded once daily. Overdue work goes to Eugene; Critical issues notify the owner immediately at the next background check. Reading or changing reminder time does not complete a task or extend its deadline.</p><p>Cash retains its full next-day deposit obligation. Approvals, payments, staff completion and owner verification remain on their existing workflows.</p><div class="rm-actions"><button class="rm-primary">Save Reminder Rules</button></div></form>
<?php elseif($tab==='contacts'):?><div class="rm-card"><h2>Independently Verify Enabled Contacts</h2><p>Confirm the person controls this contact through an independent check. This grants delivery only; it does not grant application permissions.</p><?php foreach($contacts as $contact):foreach(['email','whatsapp'] as $channel):$p=$contact['prefs'];if(!$p[$channel])continue;?><article class="rm-history"><h3><?=access_h($contact['name'])?> · <?=access_h(ucfirst($channel))?></h3><p><?=access_h($channel==='email'?$p['email_address']:$p['phone'])?></p><?php if($p[$channel.'_verified']):?><p>Ownership Verified</p><?php else:?><form method="post" class="rm-form"><?php rm_fields('verify_contact',['user_id'=>$contact['id'],'channel'=>$channel,'fingerprint'=>$s->contactToken($actor,$contact['id'],$channel)]);?><label class="rm-check"><input type="checkbox" name="verified" value="1" required>I Independently Verified That This Person Controls This Contact</label><label>Ownership Verification Evidence<textarea name="reason" minlength="12" maxlength="500" rows="2" required></textarea></label><button>Record Contact Verification</button></form><?php endif?></article><?php endforeach;endforeach;?><?php if(!$contacts):?><p>No Enabled Contacts Await Review.</p><?php endif?></div>
<?php elseif($tab==='services'):?><div class="rm-card"><h2>Delivery Services</h2><h3>Email · <?=$services['email']?'Ready':'Setup Required'?></h3><p>Requires a protected mail service configuration and a secure deployed application address.</p><h3>WhatsApp · <?=$services['whatsapp']?'Ready':'Setup Required'?></h3><p>Requires a connected business sender, approved operational message template and protected provider credentials. User consent and verified contact ownership are checked again before sending.</p><p class="rm-warning">Localhost and synthetic tests cannot send real messages. A protected background schedule is also required while the app is closed. Credentials are never entered or displayed on this page.</p></div>
<?php elseif($tab==='delivery'):?><div class="rm-card"><h2>My Delivery Log</h2><p>Messages contain a generic reminder and a secure sign-in link. Guest details, salary amounts and payment destinations remain inside the app.</p><?php foreach(array_reverse($deliveries) as $delivery):$p=$delivery['position'];?><article class="rm-history"><strong><?=access_h(ucfirst($p['channel']))?> · <?=str_starts_with($p['group'],'urgent:')?'Critical Alert':'Daily Summary'?></strong><p><?=access_h(rm_state($p['state']))?></p><small><?=access_h(display_date($delivery['created_at']))?> UTC · <?=(int)$p['attempts']?> Attempt(s)</small><details><summary>Attempt & Receipt History</summary><?php foreach($s->deliveryActivity($actor,$delivery['id']) as $event):?><p><?=access_h($event['label'])?><?=($event['state']!==''?' · '.access_h(rm_state($event['state'])):'')?><br><small><?=access_h($event['actor'])?> · <?=access_h(display_date($event['at']))?> UTC</small></p><?php endforeach?></details></article><?php endforeach?><?php if(!$deliveries):?><p>No Optional Deliveries Requested.</p><?php endif?></div><?php endif?>
<?php elseif(!$error):?><nav class="app-section-nav workspace-tab-strip" aria-label="Reminder Views"><a class="rm-button" href="<?=access_h(rm_url())?>#reminder-action" <?=!$history?'aria-current="page"':''?>>To Act On</a><a class="rm-button" href="<?=access_h(rm_url(['history'=>'1']))?>#reminder-action" <?=$history?'aria-current="page"':''?>>History</a><?php if($owner):?><a href="<?=access_h(access_url('owner-exceptions.php'))?>">Owner Exceptions</a><?php endif?></nav>
<?php if($data['heartbeat']):?><p class="rm-muted">Last Background Check: <?=access_h(display_date($data['heartbeat']['created_at']))?> UTC</p><?php else:?><p class="rm-warning">No background reminder check has been recorded. The owner can use Check Now while automatic checks are being set up.</p><?php endif?>
<?php if(!empty($data['remaining'])):?><p class="rm-warning">Some reminder checks are still pending. Check Now again or wait for the next automatic pass.</p><?php endif?><?php if(!empty($data['limited'])):?><p class="rm-warning">Some source workflows are outside your current permissions. Their private records and counts are excluded.</p><?php endif?><?php if($data['unavailable']):?><p class="rm-warning" role="alert">Some original sources are unavailable. Reminder coverage is incomplete; those sources have not been assumed resolved.</p><?php endif?>
<?php if($reminderSelected):$row=$reminderSelected['row'];?><article class="rm-card"><?php rm_button('Back To Reminders',['history'=>$history?'1':'0']);?><h2><?=access_h($row['title'])?></h2><p class="rm-state"><?=access_h($row['state'])?></p><dl class="rm-facts"><div><dt>Original Due Date</dt><dd><?=access_h($row['due']!==''?display_date($row['due']):'Not Set')?></dd></div><div><dt>Last Reminder</dt><dd><?=access_h(display_date($reminderSelected['last_reminded_at']))?> UTC</dd></div></dl><div class="rm-actions"><?php if($row['path']!==''):?><a class="rm-button rm-primary" href="<?=access_h(access_url($row['path']))?>">Open Existing Workflow</a><?php endif?><?php if(!$history&&!$row['unavailable']&&$reminderSelected['unread']):?><form method="post"><?php rm_fields('read',['id'=>$reminderSelected['id']]);?><button>Mark As Read</button></form><?php endif?></div><p class="rm-muted">Reading this reminder does not approve, pay, close or release anything. Record the action on its original workflow.</p><?php if($activity):?><h3>Reminder Activity</h3><?php foreach($activity as $event):?><div class="rm-history"><strong><?=access_h($event['label'])?></strong><small><?=access_h($event['actor'])?> · <?=access_h(display_date($event['at']))?> UTC</small></div><?php endforeach;endif?></article>
<?php else:?><div class="rm-card"><h2><?=$history?'Earlier Reminders':'To Act On'?></h2><?php if(!$data['rows']):?><p>No Current Reminders In This View.</p><?php endif?><?php foreach($data['rows'] as $item):$row=$item['row'];?><article class="rm-item"><div><small><?=access_h($row['category']??'Source Review')?><?=$item['unread']?' · Unread':''?></small><h3><?=access_h($row['title'])?></h3><p><?=access_h($row['state'])?></p><small>Due <?=access_h($row['due']!==''?display_date($row['due']):'Not Set')?> · Last Reminder <?=access_h(display_date($item['last_reminded_at']))?> UTC</small></div><div class="rm-actions"><?php if(!$history&&$row['path']!==''):?><a class="rm-button rm-primary" href="<?=access_h(access_url($row['path']))?>">Open Task</a><?php endif?>
<?php rm_button('Show Details',['id'=>$item['id'],'history'=>$history?'1':'0']);?></div></article><?php endforeach?></div><?php endif?><?php endif?>
